 (p/'summary.md').write_text('\n'.join(out)+'\n',encoding='utf-8')
 # 原始固定样本的中文可读Markdown；不复制JSON到Windows。每组前2，完整前10 JSON留服务器。
 audits=f.load(p/'pair_audit_sample.json');seen=collections.Counter();aout=['# v5.3 固定配对可读审计','', '来自数值计算前冻结的每region/target前10 strict样本；这里只呈现每组前2，完整样本留服务器JSON。没有按成功/失败选例或删除pair。人工重点核对full-body/length/既知binding；不声称所有自动pair均已人工确认纯单变量改变。','']
 for a in audits:
  pair=a['pair'];target=pair['target']
  if seen[target]>=2:continue
  seen[target]+=1;v=E[pair['pair_id']];aout+=[f'## {target}: {pair["row_a"]} ↔ {pair["row_b"]}','',f'target {pair["value_a"]} → {pair["value_b"]}；strict控制：{", ".join(pair["controls"])}；non-target differences：{", ".join(pair["different"]) or "无"}。','']
  for side in ('A','B'):
   orig=a[side];mm=a['factorized_'+side];aout += [f'**{side}：** {orig["caption"]}','', '| factorized field | value |','|---|---|']
   aout += [f'| {k} | {val or "unresolved/null"} |' for k,val in mm['labels'].items()];aout+=['', '原 structured attributes：'+line_counts(orig['attributes'])+'。','']
   for slot in f.CLOTH:
    pp=(orig.get('provenance') or {}).get(slot)
    if not pp:continue
    mentions=[]
    for m in pp.get('mentions',[]):
     text=f'{m["raw"]}[{m["start"]}:{m["end"]}]';obj=m.get('linked_object')
     if obj:text+=f' → {obj["raw"]}[{obj["start"]}:{obj["end"]}]'
     mentions.append(text)
    aout.append(f'- {slot}：'+ '；'.join(mentions))
   aout+=['', 'prototype unresolved事件：'+ ('；'.join(x['reason'] for x in mm['unresolved']) or '无')+'。','']
  aout += ['semantic energies：'+line_counts({k:fmt(x) for k,x in v['semantic'].items()})+'。','']
 aout+=['## 人工重点判断','', 'Full-body的one-piece pink/gray dress与普通dress不互斥，readout区分词形不等于真正type分离；两个稀有端点被大量复用。length pair包含short sleeve knee-length dress vs long dress，语义轴不一致。lower jeans vs pants保留了原文绑定，但pants可能包含jeans，type refinement不是所有自然pair都互斥；其它context变化同样可进入Δz。所有样本/labels/pairs原样保留，不以这些问题倒推调规则。','']
 (p/'pair_audit.md').write_text('\n'.join(aout),encoding='utf-8')
 f.save(p/'documentation_audit.json',{'summary_sha256':f.digest(p/'summary.md'),'pair_audit_sha256':f.digest(p/'pair_audit.md'),'report_source_sha256':f.digest(f.ROOT/'report.py'),'only_markdown_sync_to_windows':True})
